/* ============================================================================
   PT SUPRACOR SEJAHTERA — PATOKAN BARU: SALDO AWAL AGUSTUS (CUT-OFF 31 JULI)
   Dibuat : 05 Agustus 2026

   KENAPA BUKAN FILE JULI
     BOX_JULI.xlsx diperiksa dan TIDAK LAYAK dipakai:
        SALDO AKHIR total          -32.565 pc  (minus)
        Baris saldo akhir minus    222
        Baris rumus tidak konsisten 492 dari 4.639
     Polanya terbalik tanda, contoh 2603/00858 saldo awal 4.670 tanpa mutasi
     tapi saldo akhirnya -4.670. Itu file kerja, bukan tutup bulan yang bersih.

   KENAPA SALDO AWAL AGUSTUS
     Kolom SALDO AWAL di BOX_AGUSTUS.xlsx justru bersih:
        BOX          266 NO. OP   776.982 pc   tidak ada baris minus
        PART+LAYER    81 NO. OP   256.771 pc   2 baris minus kecil
        TOTAL                   1.033.753 pc
     Angka pembukaan bulan yang sudah diverifikasi gudang.

   KEUNGGULAN UTAMA — TIDAK BERGANTUNG PENGISIAN HARIAN
     Patokan sebelumnya (03 Agustus) ikut menyerap kolom 01-03 Agustus, yang
     ternyata punya selisih 4% terhadap database dan diisi dengan jeda.
     Dengan cut-off 31 Juli, SELURUH mutasi Agustus diambil dari database yang
     tercatat seketika. Gudang tidak perlu mengejar pengisian harian lagi, dan
     kolom 04 Agustus yang STB-nya masih kosong tidak lagi berpengaruh.

   Patokan lama diarsipkan dulu, jadi bisa dikembalikan kapan saja.
   ============================================================================ */

USE dbSopanusa;
GO
SET NOCOUNT ON;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 1 — ARSIPKAN PATOKAN LAMA
   --------------------------------------------------------------------------- */
IF OBJECT_ID('dbo.tbStokGudangExcel_BAK_0308') IS NULL
    SELECT * INTO dbo.tbStokGudangExcel_BAK_0308 FROM dbo.tbStokGudangExcel;
GO
SELECT COUNT(*) AS baris, SUM(nStokAkhirPc) AS pc, MAX(dCutOff) AS cut_off_lama
FROM   dbo.tbStokGudangExcel_BAK_0308;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 2 — ISI PATOKAN BARU, CUT-OFF 31 JULI 2026
   --------------------------------------------------------------------------- */
DELETE FROM dbo.tbStokGudangExcel;
GO

GO

GO

GO

GO

GO

GO

GO

GO

-- Petakan yang bernomor part (akhiran -P0101)
UPDATE dbo.tbStokGudangExcel
SET    cNoScDb = 'SLC/' + LEFT(RTRIM(cNoOpExcel), CHARINDEX('-', RTRIM(cNoOpExcel) + '-') - 1)
WHERE  CHARINDEX('-', cNoOpExcel) > 0;

UPDATE e SET e.cNoScDb = NULL
FROM   dbo.tbStokGudangExcel e
WHERE  NOT EXISTS (SELECT 1 FROM dbo.tbStbBJ b WHERE RTRIM(b.cNoSc) = e.cNoScDb);
GO

-- Target: BOX 266 / 776.982 pc, PART+LAYER 81 / 256.771 pc, belum_ketemu 0
SELECT cKategori, COUNT(*) AS baris,
       SUM(CASE WHEN cNoScDb IS NULL THEN 1 ELSE 0 END) AS belum_ketemu,
       SUM(nStokAkhirPc) AS total_pc, SUM(nStokAkhirKg) AS total_kg
FROM   dbo.tbStokGudangExcel GROUP BY cKategori;

SELECT cNoOpExcel, cKategori, cNama, cNamabrg, nStokAkhirPc
FROM   dbo.tbStokGudangExcel WHERE cNoScDb IS NULL ORDER BY nStokAkhirPc DESC;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 3 — HITUNG ULANG SNAPSHOT
   Prosedur membaca cut-off dari MAX(dCutOff), jadi otomatis memakai 31 Juli.
   --------------------------------------------------------------------------- */
EXEC dbo.spRefreshStokGudang @Sumber = 'PATOKAN31JUL';
GO

SELECT TOP 3 nId, nDetik, nJmlOp, nTotalPc, cStatus, cPesan
FROM   dbo.tbStokGudangLog ORDER BY nId DESC;

SELECT cStatusData, COUNT(*) AS jml_op, SUM(nStokPc) AS total_pc
FROM   dbo.tbStokGudangSnap GROUP BY cStatusData ORDER BY jml_op DESC;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 4 — JEMBATAN ANGKA
   Baris terakhir harus sama dengan isi tbStokGudangSnap.
   --------------------------------------------------------------------------- */
DECLARE @Cut DATE = '2026-07-31';
DECLARE @P INT = (SELECT SUM(nStokAkhirPc) FROM dbo.tbStokGudangExcel);
DECLARE @S INT, @K INT, @R INT;

SELECT @S = SUM(ISNULL(b.nQty,0)) FROM dbo.tbStbBJ b
WHERE  b.dTanggal > @Cut
  AND  EXISTS (SELECT 1 FROM dbo.tbStokGudangSnap x WHERE x.cNoSc = RTRIM(b.cNoSc));

SELECT @K = SUM(ISNULL(d.nQty,0))
FROM   dbo.tbSRJ s INNER JOIN dbo.tbSRJDtl d ON d.cNoSRJ = s.cNoSRJ
WHERE  s.dTanggal > @Cut
  AND  EXISTS (SELECT 1 FROM dbo.tbStokGudangSnap x
               WHERE x.cNoSc = RTRIM(COALESCE(d.cNoScDtl, s.cNoSC)));

SELECT @R = SUM(ISNULL(rv.nQty,0)) FROM dbo.vwReturnSrj rv
WHERE  rv.dTgl > @Cut
  AND  EXISTS (SELECT 1 FROM dbo.tbStokGudangSnap x WHERE x.cNoSc = RTRIM(rv.cNoSc));

SELECT 1 AS urut, 'Saldo awal Agustus (patokan)' AS komponen, @P AS pc
UNION ALL SELECT 2, 'Ditambah STB Agustus',    ISNULL(@S,0)
UNION ALL SELECT 3, 'Dikurangi kirim Agustus', -ISNULL(@K,0)
UNION ALL SELECT 4, 'Ditambah retur Agustus',  ISNULL(@R,0)
UNION ALL SELECT 5, '= STOK SISTEM HARI INI',  @P + ISNULL(@S,0) - ISNULL(@K,0) + ISNULL(@R,0)
UNION ALL SELECT 6, '  pembanding: tbStokGudangSnap',
                 (SELECT SUM(nStokPc) FROM dbo.tbStokGudangSnap)
ORDER BY urut;
GO

/* ---------------------------------------------------------------------------
   LANGKAH 5 — ADU DENGAN CATATAN GUDANG PER TANGGAL
   Kolom selisih_stb tanggal 04 Agustus akan besar, itu wajar: gudang belum
   mengisi STB tanggal tersebut. Yang perlu diperhatikan tanggal 01-03.
   --------------------------------------------------------------------------- */
;WITH db_mut AS (
    SELECT tgl, SUM(stb) AS stb, SUM(dlv) AS dlv FROM (
        SELECT CAST(dTanggal AS DATE) AS tgl, SUM(ISNULL(nQty,0)) AS stb, 0 AS dlv
        FROM   dbo.tbStbBJ WHERE dTanggal >= '2026-08-01' AND dTanggal < '2026-08-05'
        GROUP  BY CAST(dTanggal AS DATE)
        UNION ALL
        SELECT CAST(s.dTanggal AS DATE), 0, SUM(ISNULL(d.nQty,0))
        FROM   dbo.tbSRJ s INNER JOIN dbo.tbSRJDtl d ON d.cNoSRJ = s.cNoSRJ
        WHERE  s.dTanggal >= '2026-08-01' AND s.dTanggal < '2026-08-05'
        GROUP  BY CAST(s.dTanggal AS DATE)
    ) t GROUP BY tgl
)
SELECT b.tgl AS tanggal, b.stb AS stb_database, b.dlv AS dlv_database
FROM   db_mut b ORDER BY b.tgl;
GO
